using System.Runtime.InteropServices;
using cTools.Core.Models;

namespace cTools.Core.Scanning;

/// <summary>
/// 通过 <c>shell:AppsFolder</c> 枚举 Windows 自己维护的应用列表。
/// 它同时包含开始菜单注册的 Win32 应用、带 AUMID 的 Win32 应用和 UWP / MSIX 应用，
/// 比逐个读取 .lnk 更接近系统“所有应用”的视角，也能拿到打包应用。
/// </summary>
public static class AppsFolderScanner
{
    private static readonly string[] SkipPackagePrefixes =
    {
        "Microsoft.AutoGenerated",
        "Microsoft.Windows.ShellExperienceHost",
        "Microsoft.Windows.StartMenuExperienceHost",
        "Microsoft.Windows.Search",
        "Microsoft.Windows.ContentDeliveryManager",
        "Microsoft.Windows.CloudExperienceHost",
        "Microsoft.Windows.OOBE",
        "Microsoft.Windows.SecureAssessmentBrowser",
        "Microsoft.Windows.ParentalControls",
        "Microsoft.Windows.AssignedAccessLockApp",
        "Microsoft.Windows.Cortana",
        "Microsoft.Windows.XGpuEjectDialog",
        "Microsoft.Windows.PrintQueueActionCenter",
        "Microsoft.Windows.Win32WebViewHost",
        "Microsoft.Win32WebViewHost",
        "Microsoft.UI.",
        "Microsoft.VCLibs",
        "Microsoft.NET.",
        "Microsoft.Services.",
        "Microsoft.AAD.",
        "Microsoft.AccountsControl",
        "Microsoft.CredDialogHost",
        "Microsoft.LockApp",
        "Microsoft.PPIProjection",
        "MicrosoftWindows.Client."
    };

    public static IEnumerable<AppEntry> Scan()
    {
        var entries = new List<AppEntry>();
        object? shell = null;
        object? folder = null;
        object? items = null;
        try
        {
            var shellType = Type.GetTypeFromProgID("Shell.Application");
            if (shellType is null) return entries;
            shell = Activator.CreateInstance(shellType);
            if (shell is null) return entries;
            dynamic dynamicShell = shell;
            folder = dynamicShell.NameSpace("shell:AppsFolder");
            if (folder is null) return entries;
            dynamic dynamicFolder = folder;
            items = dynamicFolder.Items();
            if (items is null) return entries;
            dynamic dynamicItems = items;
            var count = (int)dynamicItems.Count;
            for (var index = 0; index < count; index++)
            {
                object? item = null;
                try
                {
                    item = dynamicItems.Item(index);
                    if (item is null) continue;
                    dynamic dynamicItem = item;
                    if ((bool)dynamicItem.IsFolder) continue;

                    var name = (string?)dynamicItem.Name;
                    var path = (string?)dynamicItem.Path;
                    if (string.IsNullOrWhiteSpace(name) || string.IsNullOrWhiteSpace(path)) continue;
                    // 应用列表里还混有网页快捷方式，直接跳过。
                    if (path.StartsWith("http://", StringComparison.OrdinalIgnoreCase)
                        || path.StartsWith("https://", StringComparison.OrdinalIgnoreCase))
                        continue;

                    var target = ReadString(dynamicItem, "System.Link.TargetParsingPath");
                    if (string.IsNullOrWhiteSpace(target) || !File.Exists(target))
                    {
                        // 部分 Win32 项的 Path 就是 exe；其余（.chm/.html）不要。
                        target = File.Exists(path) && path.EndsWith(".exe", StringComparison.OrdinalIgnoreCase)
                            ? path
                            : null;
                    }
                    if (target is not null && !target.EndsWith(".exe", StringComparison.OrdinalIgnoreCase))
                        target = null;

                    var appUserModelId = ReadString(dynamicItem, "System.AppUserModel.ID");
                    var hasAumid = !string.IsNullOrWhiteSpace(appUserModelId)
                                   && !appUserModelId.Contains('\\')
                                   && !appUserModelId.Contains('/');
                    if (!hasAumid) appUserModelId = null;

                    // 打包应用的 Path 是 AUMID，TargetParsingPath 可能为空；这类仍值得收录。
                    if (target is null && appUserModelId is null) continue;
                    if (appUserModelId is not null
                        && SkipPackagePrefixes.Any(prefix => appUserModelId.StartsWith(prefix, StringComparison.OrdinalIgnoreCase)))
                        continue;

                    var launchTarget = target ?? appUserModelId!;
                    var keywords = new List<string> { name.Trim() };
                    if (target is not null)
                    {
                        var fileName = Path.GetFileNameWithoutExtension(target);
                        if (!string.IsNullOrWhiteSpace(fileName)) keywords.Add(fileName);
                    }

                    entries.Add(new AppEntry
                    {
                        Name = name.Trim(),
                        Target = launchTarget,
                        ResolvedTarget = target ?? launchTarget,
                        AppUserModelId = appUserModelId,
                        IconPath = appUserModelId ?? target,
                        Kind = appUserModelId is null ? EntryKind.App : EntryKind.Uwp,
                        Source = EntrySource.AppsFolder,
                        Description = target ?? "Windows 应用",
                        Keywords = keywords
                    });
                }
                catch
                {
                    // 单个条目读取失败不影响其他应用。
                }
                finally
                {
                    Release(item);
                }
            }
        }
        catch (Exception ex)
        {
            Logging.Log.Error("枚举 shell:AppsFolder 失败", ex);
        }
        finally
        {
            Release(items);
            Release(folder);
            Release(shell);
        }
        return entries;
    }

    private static string? ReadString(dynamic item, string property)
    {
        try
        {
            var value = item.ExtendedProperty(property);
            var text = value as string;
            return string.IsNullOrWhiteSpace(text) ? null : text.Trim();
        }
        catch
        {
            return null;
        }
    }

    private static void Release(object? value)
    {
        if (value is not null && Marshal.IsComObject(value))
        {
            try { Marshal.FinalReleaseComObject(value); } catch { }
        }
    }
}
